CREATE TABLE IF NOT EXISTS panas_accounting_requests (request_id uuid PRIMARY KEY, reservation_id uuid NOT NULL UNIQUE, buyer_id uuid NOT NULL REFERENCES panas_accounting_buyers(buyer_id), session_id uuid NOT NULL REFERENCES panas_accounting_sessions(session_id), quote_id uuid NOT NULL UNIQUE REFERENCES panas_accounting_quotes(quote_id), idempotency_key uuid NOT NULL, signed_grant jsonb NOT NULL, status text NOT NULL CHECK(status IN ('reserved','authorized','pending','completed','failed','cancelled','refunded')), cancel_requested boolean NOT NULL DEFAULT false, authorized_at timestamptz, terminal_event_id uuid, receipt jsonb, usage_day date NOT NULL, policy_version text NOT NULL, reconcile_after timestamptz NOT NULL, created_at timestamptz NOT NULL, UNIQUE(buyer_id,idempotency_key));
